<script setup lang="ts">import {ref,onMounted} from 'vue';import {plansStore} from '../stores/plans';import {reportsStore} from '../stores/reports';import {approve} from '../api/plans';import {create} from '../api/reports';import {downloadReport} from '../api/client';import {isAdmin,canEdit} from '../stores/auth';import {useTask} from '../hooks/useTask';import PageTitle from '../components/common/PageTitle.vue';import Notice from '../components/common/Notice.vue';import StatusBadge from '../components/common/StatusBadge.vue';import PipeTable from '../components/common/PipeTable.vue';const {items,error,reload}=plansStore(),reports=reportsStore(),selected=ref<any>(null),note=ref('已复核道路施工与运维排班，允许交接执行。');const task=useTask();async function load(){await Promise.all([reload(),reports.reload()]);selected.value=items.value.find(x=>x.id===selected.value?.id)||items.value[0]}onMounted(load);function review(){task.execute(async()=>{await approve(selected.value.id,note.value);await load();task.message.value='巡检计划已审批通过。'})}function report(){task.execute(async()=>{const r=await create({name:selected.value.name+' · 正式交接',plan_id:selected.value.id});await reports.reload();await downloadReport(r.id);task.message.value='正式报告已生成并开始下载。'})}</script><template><PageTitle eyebrow="05 / FIELD HANDOVER" title="把推演，交给现场。" description="分析师生成清单，负责人审批后导出。每次交接都有明确的依据与复核记录。"/><Notice :error="error||task.error.value" :message="task.message.value"/><div class="plan-selector"><button v-for="p in items" :key="p.id" @click="selected=p" :class="{active:selected?.id===p.id}"><span>{{p.name}}</span><StatusBadge :status="p.status"/></button></div><section v-if="selected" class="section-block"><div class="section-heading"><div><h2>{{selected.name}}</h2><small class="mono">{{selected.run_id}} / {{selected.pipes.length}} 段</small></div><StatusBadge :status="selected.status"/></div><PipeTable :pipes="selected.pipes"/><div class="review-panel"><div><div class="eyebrow">RESPONSIBILITY / REVIEW</div><h2>{{selected.status==='approved'?'已完成负责人复核':'等待负责人复核'}}</h2><p>{{selected.review_note||'请检查道路施工约束、班组工时与现场安全条件，再批准交接。'}}</p><small v-if="selected.approved_by">审批人：{{selected.approved_by}}</small></div><div class="review-actions"><template v-if="selected.status==='draft'"><textarea v-if="isAdmin" v-model="note" aria-label="审批意见"/><button class="primary" v-if="isAdmin" @click="review" :disabled="task.busy.value">批准交接 →</button><p v-else>此计划需要管理员审批。</p></template><button v-if="selected.status==='approved'&&canEdit" class="primary" @click="report" :disabled="task.busy.value">生成并下载 CSV →</button><button v-for="r in reports.items.value.filter(x=>x.plan_id===selected.id)" :key="r.id" @click="task.execute(()=>downloadReport(r.id))">下载已归档报告 ↗</button></div></div></section><div v-else class="empty">尚无巡检计划。请从评估解释页生成一份预算内清单。</div></template>
